class Solution {
    public string GetPermutation(int n, int k) {

        // Raj Thomas 12th May 2026 2:31AM IST

        bool[] isUsed = new bool[n + 1];
        string res = Backtrack(n, ref k, new List<int>(), isUsed);
        return res;
    }

    private string Backtrack(int n, ref int k, List<int> items, bool[] isUsed) {

        if(items.Count == n) {
            k--;
            if(k == 0) return string.Join("", items);
            return "";
        }

        for(int i = 1; i <= n; i++) {

            if(isUsed[i]) continue;

            items.Add(i);
            isUsed[i] = true;
            string result = Backtrack(n, ref k, items, isUsed);
            if(result != "") return result;

            items.RemoveAt(items.Count - 1);
            isUsed[i] = false;
        }

        return "";
    }
}

